// MINEBENCH — STEAM TRAIN (v9)
var CX=128,CZ=180;
function _cyl(h1,h2,cx,cz,r,t){var h,x,z;for(h=h1;h<=h2;h++)for(x=-r;x<=r;x++)for(z=-r;z<=r;z++){if(x*x+z*z<=r*r)block(cx+x,h,cz+z,t);}}
function _ring(h,cx,cz,r,t){var x,z;for(x=-r;x<=r;x++)for(z=-r;z<=r;z++){if(x*x+z*z<=r*r&&x*x+z*z>(r-1)*(r-1))block(cx+x,h,cz+z,t);}}
function _box(x1,y1,z1,x2,y2,z2,t){var x,y,z;for(y=y1;y<=y2;y++)for(x=x1;x<=x2;x++)for(z=z1;z<=z2;z++)block(x,y,z,t);}
function _wheel(cx,cy,cz,r,t,hub){var a,b,i;for(a=-r;a<=r;a++)for(b=-r;b<=r;b++){if(a*a+b*b>r*r+r)continue;if(r>=5&&a*a+b*b<(r-2)*(r-2)&&a!==0&&b!==0&&Math.abs(a)!==Math.abs(b))continue;for(i=0;i<2;i++)block(cx+i,cy+b,cz+a,t);}if(hub)block(cx-1,cy,cz,hub);}
function _rod(x1,y1,z1,x2,y2,z2,t){var x,y,z;for(y=y1;y<=y2;y++)for(x=x1;x<=x2;x++)for(z=z1;z<=z2;z++)block(x,y,z,t);}
// TRACK
var t0=CZ-55,t1=CZ+55;
for(var z=t0;z<=t1;z++){for(var x=122;x<=134;x++)block(x,0,z,'cobblestone');}
for(var z=t0;z<=t1;z+=3)block(128,1,z,'oak_planks');
// BOILER - main horizontal cylinder, iron_block
_cyl(6,10,CX,CZ,5,'iron_block');
// BOILER BANDS
for(var z=CZ-12;z<=CZ+8;z+=4)_ring(8,CX,z,5,'gold_block');
// SMOKEBOX - front of boiler, slightly narrower
_cyl(6,10,CX,CZ+12,4,'iron_block');
// SMOKEBOX DOOR
for(var y=6;y<=10;y++)for(var x=CX-3;x<=CX+3;x++){block(x,y,CZ+16,'iron_block');}
// HEADLIGHT - glowstone on smokebox front
block(CX,8,CZ+17,'glowstone');
// CHIMNEY - on top of smokebox
_cyl(11,15,CX,CZ+10,2,'iron_block');
_chimney_top:for(var y=15;y<=17;y++){block(CX,y,CZ+10,'iron_block');block(CX+1,y,CZ+10,'iron_block');block(CX-1,y,CZ+10,'iron_block');block(CX,y,CZ+11,'iron_block');block(CX,y,CZ+9,'iron_block');}
// CHIMNEY LIP
for(var x=CX-2;x<=CX+2;x++)for(var z=CZ+8;z<=CZ+12;z++){block(x,18,z,'iron_block');}
// STOKING AREA - behind boiler, gold/iron
for(var dy=1;dy<=3;dy++){var sr=Math.max(1,3-dy);for(var x=-sr;x<=sr;x++)for(var z=-sr;z<=sr;z++){if(x*x+z*z<=sr*sr)block(CX+x,8+dy,CZ-8+z,'gold_block');}}
// CAB - behind boiler, higher, wood
_box(CX-5,6,CZ-16,CX+5,12,CZ-6,'oak_planks');
// CAB WINDOWS
for(var x=CX-4;x<=CX+4;x++)for(var z=CZ-15;z<=CZ-7;z++){block(x,9,CZ-16,'glass');block(x,10,CZ-16,'glass');}
// CAB ROOF
_box(CX-6,12,CZ-17,CX+6,12,CZ-5,'bricks');
// CAB DOOR (front interior)
block(CX-1,6,CZ-7,'oak_log');block(CX-1,7,CZ-7,'oak_log');block(CX-1,8,CZ-7,'oak_log');
// COWCATCHER - front cone
for(var cy=1;cy<=5;cy++){var cr=4+Math.floor((5-cy)*0.8);for(var cx2=CX-cr;cx2<=CX+cr;cx2++){block(cx2,cy,CZ+16,'iron_block');block(cx2,cy,CZ+17,'iron_block');}}
// GRILL
block(CX+2,8,CZ+17,'glowstone');
// WHEELS - 3 pairs with rods
var wheelZs=[CZ-8,CZ,CZ+8];
for(var wi=0;wi<3;wi++){var wz=wheelZs[wi];
// LEFT wheels
_wheel(CX-13,5,wz,5,'iron_block','gold_block');
// RIGHT wheels
_wheel(CX+13,5,wz,5,'iron_block','gold_block');
// CONNECTING RODS between wheels
if(wi<2){var wz2=wheelZs[wi+1];
_rod(CX-11,4,wz,CX+11,4,wz2,'iron_block');
_rod(CX-11,2,wz,CX+11,2,wz2,'iron_block');
_rod(CX+11,4,wz,CX-11,4,wz2,'iron_block');
_rod(CX+11,2,wz,CX-11,2,wz2,'iron_block');
}}
// RUNNING BOARD - red underframe above wheels
for(var z=t0;z<=t1;z++){block(CX-11,2,z,'red_wool');block(CX+11,2,z,'red_wool');}
// FRONT TENDER - between cab and boiler
var tZf=CZ+10,tZb=CZ+26,tW=7;
_box(CX-tW/2,3,tZf,CX+tW/2,3,tZb,'iron_block');
_box(CX-tW/2,4,tZf,CX+tW/2,4,tZb,'oak_planks');
// TENDER WALLS
_box(CX-tW/2,4,tZf,CX-tW/2,9,tZb,'bricks');
_box(CX+tW/2,4,tZf,CX+tW/2,9,tZb,'bricks');
_box(CX-tW/2,4,tZf,CX+tW/2,4,tZf,'bricks');
_box(CX-tW/2,4,tZb,CX+tW/2,4,tZb,'bricks');
// TENDER ROOF
_box(CX-tW/2-1,10,tZf-1,CX+tW/2+1,10,tZb+1,'bricks');
// TENDER INTERIOR - coal
for(var x=CX-tW/2+1;x<=CX+tW/2-1;x++)for(var z=tZf+1;z<=tZb-1;z++){var h=3+(Math.abs(x-CX)<2?2:0);_box(x,5,z,x,4+h,z,'black_wool');}
// TENDER WINDOWS
for(var z=tZf+2;z<=tZb-2;z+=3){_box(CX-tW/2-1,6,z,CX-tW/2-1,8,z+1,'glass');_box(CX+tW/2+1,6,z,CX+tW/2+1,8,z+1,'glass');}
// TENDER DOOR
_box(CX+tW/2+1,4,tZf+8,CX+tW/2+1,8,tZf+10,'oak_planks');
// TENDER SIDE DETAILS
for(var z=tZf;z<=tZb;z++){block(CX-tW/2,5,z,'white_wool');block(CX+tW/2,5,z,'white_wool');}
// TENDER WHEELS
var tWZs=[tZf+3,tZb-3];
for(var twi=0;twi<2;twi++){var twz=tWZs[twi];
_wheel(CX-11,4,twz,3,'iron_block','gold_block');
_wheel(CX+11,4,twz,3,'iron_block','gold_block');
}
// TENDER BOILER CONNECTOR
for(var z=tZf-1;z<=tZb;z++)block(CX,4,z,'iron_block');
// SCENERY - trees
function _tree(tx,ty,tz){var th,lx,ly,lz;for(th=0;th<5;th++)block(tx,ty+th,tz,'oak_log');for(lx=-3;lx<=3;lx++)for(ly=-2;ly<=3;ly++)for(lz=-3;lz<=3;lz++){if(lx*lx+ly*ly*1.5+lz*lz<=10)block(tx+lx,ty+4+ly,tz+lz,'oak_leaves');}}
_tree(CX-7,1,CZ-25);_tree(CX+6,1,CZ-18);_tree(CX-6,1,CZ+15);_tree(CX+8,1,CZ+28);_tree(CX-9,1,CZ+38);_tree(CX+5,1,CZ+48);
// BUSHES
function _bush(bx,by,bz){_box(bx-1,by,bz-1,bx+1,by+1,bz+1,'oak_leaves');block(bx,by+2,bz,'oak_leaves');}
_bush(CX-5,1,CZ-30);_bush(CX+4,1,CZ+8);_bush(CX-4,1,CZ+35);
// STEAM - white puffs from chimney
for(var si=0;si<8;si++){var sx=CX+((si%3)*2-2),sy=18+si,sz=CZ+9+Math.floor(si/3)-1,sr=Math.max(1,2+Math.floor(si/4));for(var x2=-sr;x2<=sr;x2++)for(var y2=-sr;y2<=sr;y2++)for(var z2=-sr;z2<=sr;z2++){if(x2*x2+y2*y2+z2*z2<=sr*sr)block(sx+x2,sy+y2,sz+z2,'white_wool');}}
// FLAG on smokebox
for(var fh=0;fh<4;fh++)block(CX,11+fh,CZ+14,'oak_log');
block(CX+1,14,CZ+14,'red_wool');block(CX+2,14,CZ+14,'red_wool');block(CX+1,13,CZ+14,'red_wool');
